           for p in c.lifting_sequence] or None
    kw = dict(unit_name=req.unit_name, depth_steps=req.depth_steps,
              **c.model_dump(exclude={"lifting_sequence"}), **s.model_dump())
    if seq:
        kw["lifting_sequence"] = seq
    return CaseInputs(**kw)

